  function fire() { if (player.attackCd > 0 || !running) return; if (chargedBeam.active || chargedBeam.cooldown > 0) { toast(`LASER OVERHEAT // ${chargedBeam.active ? 'ACTIVE' : `${Math.ceil(chargedBeam.cooldown)}s LOCKOUT`}`); return; } player.attackCd = .25; const aim = getAim(); const angle = Math.atan2(aim.y - player.y, aim.x - player.x); const rayLength = 470; world.shots.push({ x1: player.x, y1: player.y, x2: player.x + Math.cos(angle) * rayLength, y2: player.y + Math.sin(angle) * rayLength, life: .3, color: player.mode === 'boat' ? '#b5fff0' : '#f1c46e' }); for (const enemy of world.enemies) { if (enemy.dead) continue; const d = Math.hypot(enemy.x - player.x, enemy.y - player.y); const diff = Math.abs(Math.atan2(Math.sin(angle - Math.atan2(enemy.y - player.y, enemy.x - player.x)), Math.cos(angle - Math.atan2(enemy.y - player.y, enemy.x - player.x)))); if (d < rayLength && diff < .35) { const damage = 10 * damageMultiplier(); enemy.health -= damage; enemy.hit = .18; addScore(10, 'HIT', '#b5fff0', `${formatDamage(damage)} DMG`); if (enemy.health <= 0) { enemy.dead = true; player.kills++; player.materials += enemy.kind === 'godship' ? 10 : 1; addScore(enemy.kind === 'godship' ? 2000 : 100, enemy.kind === 'godship' ? `${enemy.name} DOWN` : 'CREATURE DOWN'); toast(enemy.kind === 'godship' ? `${enemy.name} DEFEATED` : 'CREATURE DOWN // DEEP MATERIAL +1'); } break; } } hitRelicShield(angle, rayLength, 10, '#b5fff0'); }
