  function updateGodProjectiles(dt) { world.godProjectiles = world.godProjectiles.filter((projectile) => { projectile.x += projectile.vx * dt; projectile.y += projectile.vy * dt; projectile.life -= dt; if (projectile.life <= 0 || !canMove(projectile.x, projectile.y)) return false; for (const enemy of world.enemies) { if (enemy.dead || projectile.hitEnemies.includes(enemy) || Math.hypot(enemy.x - projectile.x, enemy.y - projectile.y) > enemy.r + projectile.r) continue; const damage = projectile.damage * damageMultiplier(); enemy.health -= damage; enemy.hit = .35; projectile.hitEnemies.push(enemy); if (projectile.kind === 'light') igniteEnemy(enemy); if (projectile.stun > 0) enemy.stunned = Math.max(enemy.stunned, projectile.stun); addScore(projectile.kind === 'light' ? 120 : 70, projectile.kind === 'light' ? 'LIGHT BULLET' : 'DARK BULLET', projectile.color, `${formatDamage(damage)} DMG`); if (enemy.health <= 0) { enemy.dead = true; player.kills++; player.materials += enemy.kind === 'godship' ? 10 : 1; addScore(enemy.kind === 'godship' ? 2500 : 150, enemy.kind === 'godship' ? `${enemy.name} DOWN` : 'GOD BULLET HIT', projectile.color); } if (!projectile.piercing) return false; } for (const relic of world.relics) { if (relic.collected || relic.shieldBroken || projectile.hitRelics.includes(relic) || Math.hypot(relic.x - projectile.x, relic.y - projectile.y) > 34) continue; damageRelicShield(relic, projectile.damage, projectile.color); projectile.hitRelics.push(relic); if (!projectile.piercing) return false; } return true; }); }
  function godShipAttack(ship) { const colors = { lightning: '#f1c46e', water: '#8bd7e8', earth: '#c18c62', wind: '#b5fff0' }; const damage = { lightning: 72, water: 54, earth: 82, wind: 38 }; const attack = { x1: ship.x, y1: ship.y, x2: player.x, y2: player.y, color: colors[ship.type], kind: ship.type, life: .75, maxLife: .75, radius: ship.type === 'water' ? 150 : ship.type === 'wind' ? 115 : 0 }; world.godAttacks.push(attack); if (ship.type === 'water') world.specialEffects.push({ kind: 'water', x: player.x, y: player.y, radius: 150, life: .65, maxLife: .65 }); if (ship.type === 'earth') world.specialEffects.push({ kind: 'earth', x: player.x, y: player.y, radius: 90, life: .55, maxLife: .55 }); if (ship.type === 'wind') { const pushAngle = Math.atan2(player.y - ship.y, player.x - ship.x); const push = 115; if (canMove(player.x + Math.cos(pushAngle) * push, player.y + Math.sin(pushAngle) * push)) { player.x += Math.cos(pushAngle) * push; player.y += Math.sin(pushAngle) * push; } } hurt(damage[ship.type]); toast(`${ship.name} // ${ship.type.toUpperCase()} STRIKE`); }
