  function lightSpecial() { if (!godMode.active) { toast(`LIGHT CROWN // PRESS ${keyLabel(keybinds.god)} FOR GOD MODE`); return; } if (godMode.lightCooldown > 0) { toast(`LIGHT CROWN COOLDOWN // ${Math.ceil(godMode.lightCooldown)}s`); return; } godMode.lightCooldown = 6; damageShockwave('light', 330, 120, '#fff4a3'); world.specialEffects.push({ kind: 'light', x: player.x, y: player.y, radius: 330, life: .8, maxLife: .8 }); spawnGodProjectiles('light', 6, 120, .09, '#fff4a3', 1800, 0, true); toast('LIGHT CROWN // SHOCKWAVE + 6 PIERCING LIGHT BULLETS'); }
