    world.shots = world.shots.filter((shot) => { shot.life -= dt; return shot.life > 0; });
    world.scorePopups = world.scorePopups.filter((popup) => { popup.life -= dt; popup.y -= 24 * dt; return popup.life > 0; });
    world.godAttacks = world.godAttacks.filter((attack) => { attack.life -= dt; return attack.life > 0; });
