    player.attackCd = Math.max(0, player.attackCd - dt); player.dashCd = Math.max(0, player.dashCd - dt); player.invuln = Math.max(0, player.invuln - dt);
    const dx = (keys.has('d') ? 1 : 0) - (keys.has('a') ? 1 : 0); const dy = (keys.has('s') ? 1 : 0) - (keys.has('w') ? 1 : 0); const len = Math.hypot(dx, dy) || 1; const sprint = keys.has('shift') && (godMode.active || (player.stamina > 1 && !player.exhausted)); const speed = player.speed * (sprint ? 1.75 : 1) * (player.mode === 'armour' ? .5 : player.mode === 'boat' ? 1.18 : 1);
    if (dx || dy) { const moveX = dx / len * speed * dt; const moveY = dy / len * speed * dt; if (canMove(player.x + moveX, player.y)) player.x += moveX; if (canMove(player.x, player.y + moveY)) player.y += moveY; }
