  function draw() { ctx.clearRect(0, 0, W, H); ctx.save(); ctx.scale(zoom, zoom); const viewW = W / zoom, viewH = H / zoom; const cam = world.camera; ctx.translate(-cam.x, -cam.y); drawWorld(viewW, viewH); drawZones(); drawSupplies(); drawRelics(); drawTablet(); drawFamily(); drawGodAttacks(); drawSpecialEffects(); drawGodProjectiles(); drawEnemies(); drawPlayer(); drawChargedBeam(); drawObjectiveArrow(); drawShots(); drawScorePopups(); drawMotes(); ctx.restore(); }
