  function drawSpecialEffects() { world.specialEffects.forEach((effect) => { const progress = 1 - effect.life / effect.maxLife; const radius = effect.radius * progress; ctx.save(); ctx.translate(effect.x, effect.y); ctx.globalAlpha = clamp(effect.life / effect.maxLife, 0, 1); if (effect.kind === 'light') { ctx.strokeStyle = '#fff4a3'; ctx.shadowColor = '#8fe7ff'; ctx.shadowBlur = 34; ctx.lineWidth = 12; ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2); ctx.stroke(); ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 3; for (let i = 0; i < 16; i++) { const a = i * Math.PI / 8 + elapsed * 2; ctx.beginPath(); ctx.moveTo(Math.cos(a) * radius * .25, Math.sin(a) * radius * .25); ctx.lineTo(Math.cos(a) * radius * 1.14, Math.sin(a) * radius * 1.14); ctx.stroke(); } } else if (effect.kind === 'water') { ctx.strokeStyle = '#8bd7e8'; ctx.shadowColor = '#8bd7e8'; ctx.shadowBlur = 22; ctx.lineWidth = 7; ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2); ctx.stroke(); } else if (effect.kind === 'earth') { ctx.strokeStyle = '#c18c62'; ctx.shadowColor = '#c18c62'; ctx.shadowBlur = 16; ctx.lineWidth = 8; ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2); ctx.stroke(); ctx.fillStyle = '#c18c62'; for (let i = 0; i < 7; i++) { const a = i * Math.PI * 2 / 7; ctx.fillRect(Math.cos(a) * radius, Math.sin(a) * radius, 10, 10); } } else { ctx.fillStyle = 'rgba(25,9,45,.36)'; ctx.shadowColor = '#a98bdb'; ctx.shadowBlur = 36; ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = '#a98bdb'; ctx.lineWidth = 9; ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2); ctx.stroke(); ctx.strokeStyle = '#25143f'; ctx.lineWidth = 3; for (let i = 0; i < 10; i++) { const a = i * Math.PI / 5 - elapsed * .7; ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(Math.cos(a) * radius, Math.sin(a) * radius); ctx.stroke(); } } ctx.restore(); }); }
  function drawGodProjectiles() { world.godProjectiles.forEach((projectile) => { ctx.save(); ctx.translate(projectile.x, projectile.y); ctx.rotate(Math.atan2(projectile.vy, projectile.vx)); ctx.fillStyle = projectile.color; ctx.shadowColor = projectile.color; ctx.shadowBlur = 20; ctx.beginPath(); ctx.moveTo(projectile.r * 1.8, 0); ctx.lineTo(0, projectile.r); ctx.lineTo(-projectile.r * 1.4, 0); ctx.lineTo(0, -projectile.r); ctx.closePath(); ctx.fill(); ctx.restore(); }); }
  function drawPlayer() { ctx.save(); ctx.translate(player.x, player.y); const aim = getAim(); ctx.rotate(Math.atan2(aim.y - player.y, aim.x - player.x)); ctx.globalAlpha = player.invuln > 0 && Math.floor(elapsed * 12) % 2 ? .45 : 1; ctx.shadowColor = godMode.active ? '#fff4a3' : '#75e2d1'; ctx.shadowBlur = godMode.active ? 30 : 16; ctx.fillStyle = player.mode === 'boat' ? '#75b8c3' : godMode.active ? '#fff4a3' : '#d7d0ba'; ctx.beginPath(); ctx.moveTo(28, 0); ctx.lineTo(-14, -15); ctx.lineTo(-20, 0); ctx.lineTo(-14, 15); ctx.closePath(); ctx.fill(); ctx.shadowBlur = 0; ctx.fillStyle = '#142f34'; ctx.fillRect(-12, -8, 14, 16); ctx.fillStyle = godMode.active ? '#8fe7ff' : '#e4b86d'; ctx.fillRect(7, -3, 20, 6); if (keys.has('shift')) { ctx.fillStyle = godMode.active ? '#fff4a3' : '#f1c46e'; ctx.globalAlpha = .5; ctx.beginPath(); ctx.moveTo(-22, 0); ctx.lineTo(-50, -8); ctx.lineTo(-50, 8); ctx.fill(); } ctx.restore(); }
