  function loop(now) { const dt = Math.min((now - last) / 1000 || 0, .05); last = now; update(dt); draw(); requestAnimationFrame(loop); }
  requestAnimationFrame(loop);

  window.addEventListener('keydown', (e) => { const key = e.key.toLowerCase(); if (inputMap[key] || ['shift', '1', '2', 'c', ...Object.values(keybinds)].includes(key)) { e.preventDefault(); keys.add(key); } if (key === keybinds.dash) dash(); if (key === 'c') upgradeRig(); if (key === keybinds.god) activateGodMode(); if (key === keybinds.light) lightSpecial(); if (key === keybinds.darkness) darknessSpecial(); if (key === keybinds.menu && running) { running = false; showScreen('menu'); } if (key === '1') setMode('boat'); if (key === '2') setMode('armour'); });
